export function pick<T extends object>(obj: T, keys: string[]): Partial<T> {
  const out: Record<string, unknown> = {};
  for (const key of keys) {
    if (key in obj) out[key] = (obj as Record<string, unknown>)[key];
  }
  return out as Partial<T>;
}

