export async function attemptRepeatedly<T>(task: () => Promise<T>, tries = 3): Promise<T> {
  let failure: unknown;
  let remaining = tries;
  while (remaining-- > 0) {
    try {
      return await task();
    } catch (e) {
      failure = e;
    }
  }
  throw failure;
}

