export function readCookieHeader(header: string): Record<string, string> {
  return header
    .split(';')
    .filter((p) => p.includes('='))
    .reduce<Record<string, string>>((acc, p) => {
      const [name, ...rest] = p.split('=');
      acc[name.trim()] = rest.join('=').trim();
      return acc;
    }, {});
}

