export function humanSize(size: number): string {
  const suffixes = ['B', 'KB', 'MB', 'GB'];
  let amount = size;
  let index = 0;
  while (amount >= 1024 && index < suffixes.length - 1) {
    amount /= 1024;
    index++;
  }
  return `${amount.toFixed(1)} ${suffixes[index]}`;
}

